-- migration_035_merge_opioid_kbs_oct2026.sql
-- Merges KB "Opioid Phenomena - Key Definitions" with the new "Opioid Tolerance" box into ONE box "Opioid Tolerance and Related Phenomena", byte-identical on:
--   q_emq_opioid_addiction_001 -> reference (EMQ)
--   q_sba_opioid_tolerance_001 -> explanation (new in migration_034, already final there; not touched here)
-- "Opioid Receptor Physiology" (q_mtf_opioid_receptor_signalling_001) stays a separate box, byte-identical to migration_031; no update needed.
-- Idempotent.

update questions set data = jsonb_set(data, '{reference}', to_jsonb($kb$<div style="border:1px solid var(--border-strong);border-radius:14px;overflow:hidden">
  <div style="display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)">
    <span style="font-weight:700;color:#fff;font-size:14.5px">Opioid Tolerance and Related Phenomena</span>
    <div style="display:inline-flex;align-items:center;gap:7px;flex-shrink:0">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
      <span style="font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px">Knowledge</span>
    </div>
  </div>
  <div style="background:var(--surface-warm)"><div style="padding:16px 18px 14px;"><p style="margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)">Tolerance is a predictable pharmacological adaptation to repeated opioid exposure: progressively higher doses are needed to produce the same effect. It is an expected physiological response and is not, in itself, evidence of addiction. It must be distinguished from dependence, addiction, hyperalgesia, toxicity and disease progression.</p></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Tolerance: Mechanisms and Features</div><table style="margin:0"><tr><th>Point</th></tr><tr><td>Tolerance is a predictable pharmacological adaptation: progressively higher doses are needed to produce the same effect. The dose&ndash;response curve shifts to the right, developing over days to weeks and faster with higher doses</td></tr><tr><td>Mu-receptor desensitisation: phosphorylation by G-protein receptor kinases, &beta;-arrestin binding and uncoupling from the G-protein; receptor internalisation</td></tr><tr><td>Adaptive changes downstream: adenylyl cyclase upregulation (cAMP superactivation) and NMDA receptor-mediated central sensitisation</td></tr><tr><td>Develops at different rates for different effects: relatively quickly to nausea, sedation and euphoria; little or no tolerance to constipation and miosis</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Tolerance and Related Phenomena</div><table style="margin:0"><tr><th>Term</th><th>Meaning</th></tr><tr><td>Tolerance</td><td>Reduced effect at a given dose after repeated exposure, due to receptor-level neuroadaptation; expected with chronic opioid use and not itself evidence of addiction</td></tr><tr><td>Physical dependence</td><td>Withdrawal syndrome on abrupt cessation, dose reduction or antagonist administration; expected with chronic use and not addiction</td></tr><tr><td>Addiction (opioid use disorder)</td><td>Behavioural disorder: compulsive use, loss of control and continued use despite harm</td></tr><tr><td>Opioid-induced hyperalgesia</td><td>Paradoxical increase in pain sensitivity on opioids; pain may spread beyond the original site and worsens as the dose rises</td></tr><tr><td>Disease progression</td><td>New or changing pain features suggest the underlying condition has changed, rather than tolerance</td></tr><tr><td>Drug diversion</td><td>A third party (for example a carer) redirecting the patient&rsquo;s prescribed opioids for their own use or sale; a carer&rsquo;s behavioural change alongside the patient&rsquo;s rising analgesia requirements should raise this suspicion</td></tr><tr><td>Opioid toxicity</td><td>Accumulation of opioid or active metabolites (e.g. in renal impairment) causing sedation, respiratory depression, pinpoint pupils and myoclonus; unlike withdrawal, it typically causes constipation rather than diarrhoea, with progressive CNS and respiratory depression</td></tr><tr><td>Generalised anxiety disorder</td><td>Persistent, excessive worry about multiple life domains for &ge;6 months with somatic symptoms (restlessness, muscle tension, sleep disturbance); distinct from opioid-related phenomena, though it can coexist with and complicate chronic pain management</td></tr></table></div><div style="padding:16px 18px 14px;border-top:2px solid var(--border-strong);"><div style="font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px">Approach to a Falling Opioid Effect</div><table style="margin:0"><tr><th>Step</th><th>Action</th></tr><tr><td>Reassess</td><td>Look for disease progression, neuropathic component, psychosocial factors, adherence, formulation changes and interacting drugs</td></tr><tr><td>Opioid rotation</td><td>Cross-tolerance between opioids is incomplete: start the new opioid at a reduced fraction (commonly 25&ndash;50%) of the calculated equianalgesic dose</td></tr><tr><td>Limit escalation</td><td>Higher doses rarely add benefit and increase harm; review the benefit&ndash;risk balance at high doses (above 120 mg oral morphine equivalent daily) and consider reduction</td></tr><tr><td>Adjuncts</td><td>Non-opioid and neuropathic agents, NMDA antagonists in selected cases, and non-pharmacological therapies</td></tr></table></div></div>
</div>$kb$::text)) where id = 'q_emq_opioid_addiction_001';
